CREATE TABLE campaign_launches(workspace_id uuid NOT NULL REFERENCES workspaces ON DELETE CASCADE,id uuid NOT NULL DEFAULT gen_random_uuid(),connection_id uuid NOT NULL,account_id text NOT NULL,currency text NOT NULL,definition jsonb NOT NULL,steps jsonb NOT NULL,state text NOT NULL DEFAULT 'draft' CHECK(state IN('draft','building','paused','publishing','live','failed','uncertain')),approved_at timestamptz,created_by uuid NOT NULL REFERENCES users,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(workspace_id,id),FOREIGN KEY(workspace_id,connection_id) REFERENCES provider_connections(workspace_id,id) ON DELETE CASCADE);
ALTER TABLE campaign_launches ENABLE ROW LEVEL SECURITY;ALTER TABLE campaign_launches FORCE ROW LEVEL SECURITY;
CREATE POLICY launch_read ON campaign_launches FOR SELECT USING(workspace_id=nullif(current_setting('app.workspace_id',true),'')::uuid AND EXISTS(SELECT 1 FROM memberships m WHERE m.workspace_id=campaign_launches.workspace_id AND m.user_id=nullif(current_setting('app.user_id',true),'')::uuid));
CREATE POLICY launch_manage ON campaign_launches FOR ALL USING(workspace_id=nullif(current_setting('app.workspace_id',true),'')::uuid AND EXISTS(SELECT 1 FROM memberships m WHERE m.workspace_id=campaign_launches.workspace_id AND m.user_id=nullif(current_setting('app.user_id',true),'')::uuid AND m.role IN('owner','admin'))) WITH CHECK(workspace_id=nullif(current_setting('app.workspace_id',true),'')::uuid AND EXISTS(SELECT 1 FROM memberships m WHERE m.workspace_id=campaign_launches.workspace_id AND m.user_id=nullif(current_setting('app.user_id',true),'')::uuid AND m.role IN('owner','admin')));
REVOKE ALL ON campaign_launches FROM PUBLIC,northstar_app;GRANT SELECT,INSERT,UPDATE ON campaign_launches TO northstar_app;
